29	static system_state_t get_next_state(system_state_t current, system_event_t event)
30	{
31	    switch (current) {
32	        case STATE_IDLE:
33	            if (event == EVENT_BUTTON_PRESS) { g_retry_count = 0; return STATE_RECORDING; }
34	            return current;
35	        case STATE_RECORDING:
36	            if (event == EVENT_RECORD_DONE || event == EVENT_RECORD_TIMEOUT) return STATE_UPLOADING;
37	            if (event == EVENT_ERROR) return STATE_IDLE;
38	            return current;
39	        case STATE_UPLOADING:
40	            if (event == EVENT_UPLOAD_SUCCESS) return STATE_PLAYING;
41	            if (event == EVENT_UPLOAD_FAIL) {
42	                g_retry_count++;
43	                if (g_retry_count >= MAX_RETRY_COUNT) return STATE_IDLE;
44	                return STATE_ERROR;
45	            }
46	            return current;
47	        case STATE_PLAYING:
48	            if (event == EVENT_PLAY_DONE) return STATE_IDLE;
49	            return current;
50	        case STATE_ERROR:
51	            if (event == EVENT_BUTTON_PRESS) { g_retry_count = 0; return STATE_IDLE; }
52	            if (event == EVENT_RETRY) return STATE_UPLOADING;
53	            return current;
54	    }
55	    return STATE_IDLE;
56	}
